from pathlib import Path
from decimal import Decimal, InvalidOperation
import re

CASE_ID = "CASE-2026-00478"
REQUIRED_HEADERS = {
    1: "Case ID",
    6: "Appeal Type",
    9: "Date of Receipt",
    10: "Acknowledgment Due",
    15: "Decision Due",
}
CELL_REFERENCE = re.compile(
    r"^\$?([A-Z]{1,3})(\$?)([1-9][0-9]*)$",
    re.IGNORECASE,
)

def fail(feedback):
    return {"pass": False, "score": 0.0, "feedback": feedback}

def normalize_text(value):
    if not isinstance(value, str):
        return None
    return " ".join(value.split()).casefold()

def locate_workbook(workspace_path):
    workspace = Path(workspace_path)
    matches = sorted(path for path in workspace.rglob("appeals_log_master.xlsx") if path.is_file())
    if not matches:
        return None, "appeals_log_master.xlsx not found"
    if len(matches) != 1:
        return None, f"Expected one appeals_log_master.xlsx, found {len(matches)}."
    return matches[0], None

def log_sheets(workbook):
    return [
        sheet for sheet in workbook.worksheets
        if all(normalize_text(sheet.cell(row=2, column=column).value) == label.casefold()
               for column, label in REQUIRED_HEADERS.items())
    ]

def case_rows(sheets):
    matches = []
    for sheet in sheets:
        for row_num in range(3, sheet.max_row + 1):
            value = sheet.cell(row=row_num, column=1).value
            if isinstance(value, str) and value.strip() == CASE_ID:
                matches.append((sheet, row_num))
    return matches

def is_row_relative_cell(token, column, row_num):
    if token.type != "OPERAND" or token.subtype != "RANGE":
        return False
    match = CELL_REFERENCE.fullmatch(token.value)
    if match is None:
        return False
    token_column, absolute_row, token_row = match.groups()
    return token_column.upper() == column and absolute_row == "" and int(token_row) == row_num

def text_value(token):
    if token.type != "OPERAND" or token.subtype != "TEXT":
        return None
    return token.value[1:-1].replace('""', '"')

def matching_close(tokens, open_index):
    depth = 0
    for index in range(open_index, len(tokens)):
        token = tokens[index]
        if token.type in {"FUNC", "PAREN"} and token.subtype == "OPEN":
            depth += 1
        elif token.type in {"FUNC", "PAREN"} and token.subtype == "CLOSE":
            depth -= 1
            if depth == 0:
                return index
    return None

def strip_balanced_parentheses(tokens):
    expression = list(tokens)
    while (
        len(expression) >= 2
        and expression[0].type == "PAREN"
        and expression[0].subtype == "OPEN"
        and matching_close(expression, 0) == len(expression) - 1
    ):
        expression = expression[1:-1]
    return expression

def function_arguments(tokens, function_name):
    expression = strip_balanced_parentheses(tokens)
    if not expression:
        return None
    opening = expression[0]
    if not (
        opening.type == "FUNC"
        and opening.subtype == "OPEN"
        and opening.value.upper() == function_name.upper() + "("
        and matching_close(expression, 0) == len(expression) - 1
    ):
        return None

    arguments = []
    argument_start = 1
    depth = 0
    for index in range(1, len(expression) - 1):
        token = expression[index]
        if token.type in {"FUNC", "PAREN"} and token.subtype == "OPEN":
            depth += 1
        elif token.type in {"FUNC", "PAREN"} and token.subtype == "CLOSE":
            depth -= 1
        elif token.type == "SEP" and token.subtype == "ARG" and depth == 0:
            arguments.append(expression[argument_start:index])
            argument_start = index + 1
    arguments.append(expression[argument_start:-1])
    return arguments

def is_exact_concurrent_search(tokens, row_num):
    expression = strip_balanced_parentheses(tokens)
    isnumber_arguments = function_arguments(expression, "ISNUMBER")
    if isnumber_arguments is not None:
        if len(isnumber_arguments) != 1:
            return False
        expression = strip_balanced_parentheses(isnumber_arguments[0])

    search_arguments = function_arguments(expression, "SEARCH")
    if search_arguments is None or len(search_arguments) != 2:
        return False
    phrase = strip_balanced_parentheses(search_arguments[0])
    reference = strip_balanced_parentheses(search_arguments[1])
    return (
        len(phrase) == 1
        and normalize_text(text_value(phrase[0])) == "concurrent care"
        and len(reference) == 1
        and is_row_relative_cell(reference[0], "F", row_num)
    )

def is_exact_offset(tokens, row_num, offset):
    expression = strip_balanced_parentheses(tokens)
    if len(expression) != 3:
        return False
    reference, operator, number = expression
    if not is_row_relative_cell(reference, "I", row_num):
        return False
    if operator.type != "OPERATOR-INFIX" or operator.value != "+":
        return False
    if number.type != "OPERAND" or number.subtype != "NUMBER":
        return False
    try:
        return Decimal(number.value) == Decimal(offset)
    except (InvalidOperation, ValueError):
        return False

def is_exact_empty_text(tokens):
    expression = strip_balanced_parentheses(tokens)
    return (
        len(expression) == 1
        and text_value(expression[0]) == ""
    )

def is_exact_blank_date_guard(tokens, row_num):
    expression = strip_balanced_parentheses(tokens)
    if len(expression) != 3:
        return False
    reference, operator, blank = expression
    return (
        is_row_relative_cell(reference, "I", row_num)
        and operator.type == "OPERATOR-INFIX"
        and operator.value == "="
        and text_value(blank) == ""
    )

def is_root_qualifying_if(tokens, row_num, offset):
    arguments = function_arguments(tokens, "IF")
    if arguments is None or len(arguments) != 3:
        return False
    condition, true_branch, _false_branch = arguments
    return (
        is_exact_concurrent_search(condition, row_num)
        and is_exact_offset(true_branch, row_num, offset)
    )

def has_qualifying_if(tokens, row_num, offset):
    if is_root_qualifying_if(tokens, row_num, offset):
        return True

    arguments = function_arguments(tokens, "IF")
    if arguments is None or len(arguments) != 3:
        return False
    condition, true_branch, false_branch = arguments
    return (
        is_exact_blank_date_guard(condition, row_num)
        and is_exact_empty_text(true_branch)
        and is_root_qualifying_if(false_branch, row_num, offset)
    )

def inspect_formula(formula, row_num, offset, tokenizer):
    if not isinstance(formula, str) or not formula.startswith("="):
        return False, "expected a formula"
    try:
        tokens = [token for token in tokenizer(formula).items if token.type != "WSPACE"]
    except Exception as exc:
        return False, f"formula could not be parsed ({exc})"
    if has_qualifying_if(tokens, row_num, offset):
        return True, ""
    return False, (
        f"expected a genuine IF with a SEARCH condition for exact text 'Concurrent Care' "
        f"against exact row-relative F{row_num} whose true branch is the complete exact "
        f"I{row_num}+{offset} operation using exact row-relative I{row_num}"
    )

def verify(workspace_path, external_services_path=None):
    try:
        import openpyxl
        from openpyxl.formula import Tokenizer
    except ImportError:
        return fail("openpyxl not available")

    xlsx_path, error = locate_workbook(workspace_path)
    if error:
        return fail(error)
    try:
        workbook = openpyxl.load_workbook(str(xlsx_path), data_only=False)
    except Exception as exc:
        return fail(f"Could not open appeals_log_master.xlsx: {exc}")

    try:
        sheets = log_sheets(workbook)
        if len(sheets) != 1:
            return fail(f"Expected one well-formed Appeals Log sheet, found {len(sheets)}.")
        matches = case_rows(sheets)
        if not matches:
            return fail(f"No row with exact Case ID '{CASE_ID}' found in column A.")
        if len(matches) != 1:
            locations = [f"{sheet.title}!A{row}" for sheet, row in matches]
            return fail(f"Duplicate rows with exact Case ID '{CASE_ID}' found: {locations}.")

        sheet, case_row = matches[0]
        checks = {
            "J": (10, 1, "Acknowledgment Due"),
            "O": (15, 3, "Decision Due"),
        }
        results = []
        overall_pass = True
        for column, (column_index, offset, label) in checks.items():
            formula = sheet.cell(row=case_row, column=column_index).value
            passed, detail = inspect_formula(formula, case_row, offset, Tokenizer)
            if passed:
                results.append(
                    f"Column {column} ({label}) on case row {case_row}: PASS — formula has "
                    f"a genuine Concurrent Care IF with complete true-branch I{case_row}+{offset}."
                )
            else:
                results.append(
                    f"Column {column} ({label}) on case row {case_row}: FAIL — {detail}; "
                    f"found '{str(formula)[:120]}'."
                )
                overall_pass = False
        return {
            "pass": overall_pass,
            "score": 1.0 if overall_pass else 0.0,
            "feedback": "\n".join(results),
        }
    finally:
        workbook.close()

