from pathlib import Path
import openpyxl

CASE_ID = "CASE-2026-00478"
REQUIRED_HEADERS = {
    1: "Case ID",
    11: "Acknowledgment Sent",
    18: "Compliance Escalation",
    19: "Related Case ID",
    20: "Decision Date",
    21: "Outcome",
}

def fail(feedback, score=0.0):
    return {"pass": False, "score": score, "feedback": feedback}

def normalize_text(value):
    if not isinstance(value, str):
        return None
    return " ".join(value.split()).casefold()

def is_blank(value):
    return value is None or (isinstance(value, str) and value.strip() == "")

def locate_workbook(workspace_path):
    workspace = Path(workspace_path)
    matches = sorted(path for path in workspace.rglob("appeals_log_master.xlsx") if path.is_file())
    if not matches:
        return None, "appeals_log_master.xlsx not found"
    if len(matches) != 1:
        return None, f"Expected one appeals_log_master.xlsx, found {len(matches)}."
    return matches[0], None

def log_sheets(workbook):
    return [
        sheet for sheet in workbook.worksheets
        if all(normalize_text(sheet.cell(row=2, column=column).value) == label.casefold()
               for column, label in REQUIRED_HEADERS.items())
    ]

def case_rows(sheets):
    matches = []
    for sheet in sheets:
        for row_num in range(3, sheet.max_row + 1):
            value = sheet.cell(row=row_num, column=1).value
            if isinstance(value, str) and value.strip() == CASE_ID:
                matches.append((sheet, row_num))
    return matches

def verify(workspace_path, external_services_path=None):
    file_path, error = locate_workbook(workspace_path)
    if error:
        return fail(error)
    try:
        workbook = openpyxl.load_workbook(file_path, data_only=False)
    except Exception as exc:
        return fail(f"Could not open appeals_log_master.xlsx: {exc}")

    try:
        sheets = log_sheets(workbook)
        if len(sheets) != 1:
            return fail(f"Expected one well-formed Appeals Log sheet, found {len(sheets)}.")
        matches = case_rows(sheets)
        if not matches:
            return fail(f"No row with exact Case ID '{CASE_ID}' found in column A.")
        if len(matches) != 1:
            locations = [f"{sheet.title}!A{row}" for sheet, row in matches]
            return fail(f"Duplicate rows with exact Case ID '{CASE_ID}' found: {locations}.")

        sheet, row_num = matches[0]
        must_be_blank = {
            "K": (11, "Acknowledgment Sent"),
            "S": (19, "Related Case ID"),
            "T": (20, "Decision Date"),
            "U": (21, "Outcome"),
        }
        passed_checks = 0
        issues = []
        for column, (column_index, label) in must_be_blank.items():
            value = sheet.cell(row=row_num, column=column_index).value
            if is_blank(value):
                passed_checks += 1
            else:
                issues.append(f"{column} ({label}) should be blank but has value '{value}'.")

        compliance = sheet.cell(row=row_num, column=18).value
        if is_blank(compliance) or normalize_text(compliance) == "n":
            passed_checks += 1
        else:
            issues.append(f"R (Compliance Escalation) should be blank or 'N' but has value '{compliance}'.")

        if issues:
            return fail(f"Issues in {CASE_ID} row {row_num}: " + " ".join(issues), passed_checks / 5)
        return {
            "pass": True,
            "score": 1.0,
            "feedback": f"All required blank or N fields in {CASE_ID} row {row_num} meet the criteria.",
        }
    finally:
        workbook.close()

from pathlib import Path
from datetime import date, datetime
import openpyxl

def fail(feedback):
    return {"pass": False, "score": 0.0, "feedback": feedback}

def normalize(value):
    return " ".join(str(value or "").split()).casefold()

def parse_date(value):
    if isinstance(value, datetime):
        return value.date()
    if isinstance(value, date):
        return value
    text = str(value or "").strip()
    for fmt in ("%m/%d/%Y", "%m/%d/%y", "%Y-%m-%d", "%B %d, %Y", "%b %d, %Y"):
        try:
            return datetime.strptime(text, fmt).date()
        except ValueError:
            pass
    return None

def verify(workspace_path, external_services_path=None):
    matches = sorted(path for path in Path(workspace_path).rglob("appeals_log_master.xlsx") if path.is_file())
    if len(matches) != 1:
        return fail(f"Expected one appeals_log_master.xlsx, found {len(matches)}")
    try:
        workbook = openpyxl.load_workbook(matches[0], data_only=True)
    except Exception as exc:
        return fail(f"Could not open appeals_log_master.xlsx: {exc}")
    try:
        sheets = [
            sheet for sheet in workbook.worksheets
            if normalize(sheet.cell(row=2, column=1).value) == "case id"
            and normalize(sheet.cell(row=2, column=15).value) == "decision due"
        ]
        if len(sheets) != 1:
            return fail(f"Expected one Appeals Log sheet with Case ID and Decision Due headers, found {len(sheets)}")
        sheet = sheets[0]
        records = []
        for row_index in range(3, sheet.max_row + 1):
            case_id = str(sheet.cell(row=row_index, column=1).value or "").strip()
            if not case_id:
                continue
            due = parse_date(sheet.cell(row=row_index, column=15).value)
            if due is None:
                return fail(f"Case {case_id} in row {row_index} has no parseable Decision Due date")
            records.append((row_index, case_id, due))
        if not any(case_id.casefold() == "case-2026-00478" for _, case_id, _ in records):
            return fail("CASE-2026-00478 is missing from the appeals log")
        due_dates = [due for _, _, due in records]
        if due_dates != sorted(due_dates):
            return fail("Appeals are not sorted by ascending Decision Due: " + str(records))
        return {"pass": True, "score": 1.0, "feedback": f"All {len(records)} populated appeal records, including CASE-2026-00478, are sorted by ascending Decision Due."}
    finally:
        workbook.close()
